#!/bin/sh
# Copies the model catalog generated by sdk-core (contract/catalog.json) into the Swift package
# resources. Run after `node packages/sdk-core/scripts/export-contract.mjs`. A test
# (ContractTests.bundledCatalogMatchesSdkCoreContract) fails when the two drift.
set -e
here="$(cd "$(dirname "$0")/.." && pwd)"
cp "$here/../sdk-core/contract/catalog.json" "$here/Sources/Natif/Resources/catalog.json"
echo "Synced catalog.json"
